import csv
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt

### Generated by Claude Code to create graphs/visualization and CSV file from analyze.py 
### for average of 20 runs of experiment 


# usage: python plot.py   (reads results.csv from average.py, writes scaling.png / scaling.pdf)
rows = list(csv.DictReader(open("results.csv")))
threads = [int(r["threads"]) for r in rows]
serial = [float(r["serial_s"]) for r in rows]
p1 = [float(r["p1_s"]) for r in rows]
p2 = [float(r["p2_s"]) for r in rows]
s1 = [float(r["p1_speedup"]) for r in rows]
s2 = [float(r["p2_speedup"]) for r in rows]

SURFACE = "#fcfcfb"
INK = "#0b0b0b"
INK2 = "#52514e"
GRID = "#e4e3df"
BLUE = "#2a78d6"     # integration
ORANGE = "#eb6834"   # monte carlo

fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(10, 4.2), facecolor=SURFACE)

def style(ax, ylabel, title):
    ax.set_facecolor(SURFACE)
    ax.set_xscale("log", base=2)
    ax.set_yscale("log")
    ax.set_xticks(threads)
    ax.set_xticklabels(threads)
    ax.minorticks_off()
    ax.set_xlabel("threads", color=INK2)
    ax.set_ylabel(ylabel, color=INK2)
    ax.set_title(title, color=INK, loc="left", fontsize=11)
    ax.grid(True, color=GRID, linewidth=0.8)
    ax.tick_params(colors=INK2)
    for side in ("top", "right"):
        ax.spines[side].set_visible(False)
    for side in ("left", "bottom"):
        ax.spines[side].set_color(GRID)

def line(ax, y, color, label):
    ax.plot(threads, y, color=color, linewidth=2, marker="o", markersize=7,
            markeredgecolor=SURFACE, markeredgewidth=2, label=label)

# runtime
style(ax1, "mean time (s)", "Runtime, 100M steps (mean of 20 runs)")
line(ax1, p1, BLUE, "Integration (P1)")
line(ax1, p2, ORANGE, "Monte Carlo (P2)")
ax1.axhline(sum(serial) / len(serial), color=INK2, linewidth=1.5, linestyle="--", label="Serial integration")
ax1.legend(frameon=False, labelcolor=INK, fontsize=9)

# speedup
style(ax2, "speedup vs. serial", "Speedup")
ax2.plot(threads, threads, color=INK2, linewidth=1.5, linestyle="--", label="Ideal (speedup = threads)")
line(ax2, s1, BLUE, "Integration (P1)")
line(ax2, s2, ORANGE, "Monte Carlo (P2)")
ax2.set_yticks([1, 2, 4, 8, 16, 32, 64])
ax2.set_yticklabels([1, 2, 4, 8, 16, 32, 64])
ax2.legend(frameon=False, labelcolor=INK, fontsize=9, loc="upper left")

fig.tight_layout()
fig.savefig("scaling.png", dpi=200, facecolor=SURFACE)
fig.savefig("scaling.pdf", facecolor=SURFACE)
